const LOGO='data:image/png;base64,';
const RAY='data:image/png;base64,';
const TOMY='data:image/png;base64,';

function initShared(){
  document.querySelectorAll('[data-logo]').forEach(el=>el.src=LOGO);
  document.querySelectorAll('[data-ray]').forEach(el=>el.src=RAY);
  document.querySelectorAll('[data-tomy]').forEach(el=>el.src=TOMY);

  const cursor=document.getElementById('cursor');
  const trail=document.getElementById('cursor-trail');
  if(cursor){
    document.addEventListener('mousemove',e=>{
      cursor.style.left=e.clientX+'px';cursor.style.top=e.clientY+'px';
      trail.style.left=e.clientX+'px';trail.style.top=e.clientY+'px';
    });
  }

  window.addEventListener('scroll',()=>{
    const pct=(window.scrollY/(document.body.scrollHeight-window.innerHeight))*100;
    const bar=document.getElementById('scroll-bar');
    if(bar)bar.style.width=pct+'%';
  });

  const observer=new IntersectionObserver((entries)=>{
    entries.forEach((e,i)=>{
      if(e.isIntersecting)setTimeout(()=>e.target.classList.add('visible'),i*80);
    });
  },{threshold:0.1});
  document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));

  let lang='en';
  window.setLang=function(l){
    lang=l;
    document.querySelectorAll('.lang-btn').forEach(b=>b.classList.toggle('active',b.textContent===l.toUpperCase()));
    document.querySelectorAll('[data-en]').forEach(el=>{
      const t=el.getAttribute('data-'+l);
      if(t)el.innerHTML=t;
    });
  };

  const page=window.location.pathname.split('/').pop()||'index.html';
  document.querySelectorAll('.nav-links a').forEach(a=>{
    const href=a.getAttribute('href');
    if(href&&(href===page||href.endsWith(page)))a.classList.add('active');
  });
}
document.addEventListener('DOMContentLoaded',initShared);
